  ((SELECT id FROM sls WHERE kode_sls = '5205040004001700'), '45c55e21-c966-4aeb-b10a-76b7d666b0f6#1', 'UTP TANAMAN PANGAN <SYAMSURIZAL>', 'SYAMSURIZAL', 'keluarga', 'A', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SUBMITTED BY Pencacah', '2026-08-10 06:29:56', '2026-08-10 17:09:52'),
  ((SELECT id FROM sls WHERE kode_sls = '5205040004001700'), '45c55e21-c966-4aeb-b10a-76b7d666b0f6#2', 'UTP HORTIKULTURA BAWANG MERAH (SYAMSURIZAL)', 'SYAMSURIZAL', 'keluarga', 'A', '[A] 01134 Pertanian Sayuran Umbi', 38000000.0, NULL, 14500000.0, NULL, 8500000.0, NULL, 5000000.0, NULL, 1000000.0, NULL, 0.0, NULL, 8, 'Membudidayakan bawang merah di lahan pertanian milik sendiri atau sewa. Kegiatan dimulai dari pengolahan dan pembersihan lahan, pembuatan bedengan, penyiapan serta penanaman bibit bawang merah, kemudian dilakukan pemupukan, penyiraman, penyiangan gulma, dan pengendalian hama serta penyakit secara rutin. Setelah tanaman cukup umur, bawang merah dipanen dengan cara dicabut, kemudian dikeringkan dan dibersihkan sebelum dijual kepada pengepul atau konsumen.', 'SUBMITTED BY Pencacah', '2026-08-10 06:29:56', '2026-08-10 17:09:52'),
  ((SELECT id FROM sls WHERE kode_sls = '5205040004001700'), '45c55e21-c966-4aeb-b10a-76b7d666b0f6#3', 'UTP PETERNAKAN <SYAMSURIZAL>', 'SYAMSURIZAL', 'keluarga', 'A', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SUBMITTED BY Pencacah', '2026-08-10 06:29:56', '2026-08-10 17:09:52'),
