  ((SELECT id FROM sls WHERE kode_sls = '5205040006000600'), 'ce400ca6-8348-4573-8fd9-dc74036da2af#1', 'UD MAURIN <Saharuddin >', NULL, 'UMKM', 'G', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SUBMITTED BY Pencacah', '2026-07-23 02:52:36', '2026-08-10 17:09:52'),
  ((SELECT id FROM sls WHERE kode_sls = '5205040006000600'), 'd08132be-ed2f-4a63-b3ed-8aaf0d1d3d2a#1', 'UTP PETERNAKAN <SAHIDIN>', 'JURAIDAH', 'keluarga', 'A', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SUBMITTED BY Pencacah', '2026-08-01 10:26:27', '2026-08-10 17:09:52'),
  ((SELECT id FROM sls WHERE kode_sls = '5205040006000600'), 'd08132be-ed2f-4a63-b3ed-8aaf0d1d3d2a#1002', 'JUALAN KELILING MAKANAN (JURAIDAH)', 'JURAIDAH', 'keluarga', 'I', '[I][56102]Aktivitas Penyediaan Makanan di Bangunan Tidak Tetap', 24000000.0, NULL, 18000000.0, NULL, 16500000.0, NULL, 0.0, NULL, 1500000.0, NULL, 0.0, NULL, 0, 'Menjual makanan siap saji berupa pecal, urap, dan aneka gorengan secara keliling (bakulan) dengan menawarkan langsung kepada pembeli dari satu lokasi ke lokasi lain menggunakan peralatan sederhana. Produk dijual eceran untuk konsumsi sehari-hari.', 'SUBMITTED BY Pencacah', '2026-08-01 10:26:27', '2026-08-10 17:09:52'),
